//! Zenith Semantic Analyzer
//!
//! This module performs semantic analysis on the Abstract Syntax Tree (AST)
//! generated by the parser. It ensures that the Zenith program is meaningful
//! and adheres to the language's complex semantic rules, type system, and
//! various computational paradigms (classical, quantum, nano).
//!
//! Key responsibilities include:
//! - Type Checking: Validating type compatibility for expressions and assignments,
//!   handling type inference, and ensuring correctness across basic, quantum,
//!   nano, universe, dependent, linear, affine, and session types.
//! - Scope Resolution: Managing symbol tables for variable, function, type, and
//!   effect declarations, resolving identifiers to their correct definitions.
//! - EVAS Compliance: Verifying adherence to the Ethical, Verifiable, Autonomous,
//!   and Secure (EVAS) framework, especially for 'unsafe!(evas:{proof})' blocks.
//! - Effect System Validation: Ensuring proper handling and dispatch of algebraic effects.
//! - Memory Model Validation: Checking hybrid memory model rules (GC, ARC, ownership, manual).
//! - Concurrency Model Validation: Ensuring safe concurrent operations across
//!   async/await, actor, CSP, and parallel data processing models.
//! - Sankofa-specific checks: Validating memory access patterns, learning rules,
//!   wisdom distillation, and temporal constructs (zamani, sasa, history).
//! - Quantum/Nano-specific checks: Validating quantum circuit operations, nano-agent
//!   specifications, and MTS literal usage.
//! - Control Flow Analysis: Detecting unreachable code, uninitialized variables.
//! - Data Flow Analysis: Tracking data propagation and potential hazards.

use crate::ast::{Program, Statement, Expression, Literal, Identifier, TypeAnnotation};
use crate::tokens::Span; // For error reporting
use crate::compiler_types::{Type, SymbolTable, Scope, SemanticError}; // Conceptual types
use std::collections::HashMap;

// --- Semantic Analyzer Structure ---
pub struct SemanticAnalyzer<'a> {
    // Reference to the program's source code or file for error reporting
    source_name: &'a str,
    // Accumulate semantic errors
    errors: Vec<SemanticError>,
    // Manages scopes and symbols
    symbol_table: SymbolTable,
    // Type system definitions and rules
    type_system_rules: HashMap<String, Type>, // Conceptual: e.g., "int" -> Type::Int, "Qubit" -> Type::Quantum
    // Other state needed for analysis (e.g., current function, loop depth)
    current_function_return_type: Option<Type>,
}

impl<'a> SemanticAnalyzer<'a> {
    pub fn new(source_name: &'a str) -> Self {
        SemanticAnalyzer {
            source_name,
            errors: Vec::new(),
            symbol_table: SymbolTable::new(),
            type_system_rules: Self::load_zenith_type_rules(),
            current_function_return_type: None,
        }
    }

    fn load_zenith_type_rules() -> HashMap<String, Type> {
        let mut map = HashMap::new();
        // Basic types
        map.insert("int".to_string(), Type::Int);
        map.insert("float".to_string(), Type::Float);
        map.insert("bool".to_string(), Type::Boolean);
        map.insert("string".to_string(), Type::String);
        map.insert("char".to_string(), Type::Char);
        // Quantum types
        map.insert("Qubit".to_string(), Type::QuantumQubit);
        map.insert("QReg".to_string(), Type::QuantumQReg(0)); // Placeholder
        map.insert("Superposition".to_string(), Type::QuantumSuperposition(Box::new(Type::Unknown)));
        // Nano types
        map.insert("Atom".to_string(), Type::NanoAtom(Box::new(Type::Unknown)));
        map.insert("Molecule".to_string(), Type::NanoMolecule(Box::new(Type::Unknown)));
        // Sankofa types
        map.insert("History".to_string(), Type::SankofaHistory(Box::new(Type::Unknown)));
        map.insert("ConsensusTrue".to_string(), Type::SankofaConsensus(Box::new(Type::Unknown)));
        // ... many more types from ZENITH Universal Trinity Type System v2.0
        map
    }

    pub fn analyze(&mut self, program: &Program) -> bool {
        println!("Performing semantic analysis on program...");
        self.symbol_table.enter_scope(); // Global scope

        for stmt in &program.statements {
            self.analyze_statement(stmt);
        }

        self.symbol_table.exit_scope(); // Exit global scope
        !self.errors.is_empty() // Return true if errors found
    }

    fn analyze_statement(&mut self, stmt: &Statement) {
        match stmt {
            Statement::Let(span, name, expr) => {
                let expr_type = self.analyze_expression(expr);
                // Conceptual: Perform type inference or check against explicit type annotation
                // If 'let x: Type = expr;' check expr_type against Type
                self.symbol_table.define_symbol(name.clone(), expr_type.clone(), span.clone());
                println!("  Defined symbol '{}' with type {:?}", name, expr_type);
            }
            Statement::Return(span, expr) => {
                let expr_type = self.analyze_expression(expr);
                if let Some(expected_return_type) = &self.current_function_return_type {
                    if !self.is_assignable(&expr_type, expected_return_type) {
                        self.errors.push(SemanticError::new(
                            format!("Return type mismatch: expected {:?}, found {:?}.", expected_return_type, expr_type),
                            span.clone(),
                        ));
                    }
                } else {
                    self.errors.push(SemanticError::new(
                        "Return statement outside function.".to_string(),
                        span.clone(),
                    ));
                }
            }
            Statement::Expression(expr) => {
                self.analyze_expression(expr);
            }
            Statement::Function(span, name, params, body) => {
                // Conceptual: Define function symbol
                // Store original function return type (e.g., from a signature)
                let original_return_type = Type::Unknown; // Placeholder
                self.current_function_return_type = Some(original_return_type.clone());
                self.symbol_table.define_symbol(name.clone(), Type::Function(Box::new(Type::Unknown), Box::new(original_return_type.clone())), span.clone());

                self.symbol_table.enter_scope(); // Function scope
                // Conceptual: Define parameters in scope
                self.analyze_expression(body); // Analyze function body (which is a block expression)
                self.symbol_table.exit_scope(); // Exit function scope
                self.current_function_return_type = None;
            }
            Statement::QuantumCircuit(span, name, body) => {
                self.symbol_table.define_symbol(name.clone(), Type::QuantumCircuit, span.clone());
                self.symbol_table.enter_scope(); // Quantum circuit scope
                // Conceptual: Validate quantum operations, qubit allocations, etc.
                self.analyze_expression(body); // Analyze circuit body
                self.symbol_table.exit_scope();
            }
            Statement::NanoAgent(span, name, body) => {
                self.symbol_table.define_symbol(name.clone(), Type::NanoAgent, span.clone());
                self.symbol_table.enter_scope(); // Nano-agent scope
                // Conceptual: Validate nano-agent behaviors, communication protocols
                self.analyze_expression(body); // Analyze agent body
                self.symbol_table.exit_scope();
            }
            Statement::SankofaMemory(span, name, expr) => {
                let expr_type = self.analyze_expression(expr);
                self.symbol_table.define_symbol(name.clone(), Type::SankofaMemory(Box::new(expr_type.clone())), span.clone());
                // Conceptual: Additional Sankofa-specific checks for memory consistency, temporal validity
            }
        }
    }

    fn analyze_expression(&mut self, expr: &Expression) -> Type {
        match expr {
            Expression::Identifier(Identifier(name, span)) => {
                if let Some(symbol) = self.symbol_table.resolve_symbol(name) {
                    println!("  Resolved identifier '{}' to type {:?}", name, symbol.typ);
                    symbol.typ.clone()
                } else {
                    self.errors.push(SemanticError::new(
                        format!("Undeclared identifier '{}'.", name),
                        span.clone(),
                    ));
                    Type::Error // Return error type
                }
            }
            Expression::Literal(literal) => {
                match literal {
                    Literal::Integer(_, _) => Type::Int,
                    Literal::Float(_, _) => Type::Float,
                    Literal::String(_, _) => Type::String,
                    Literal::Boolean(_, _) => Type::Boolean,
                    Literal::Char(_, _) => Type::Char,
                    Literal::Quantum(_, _) => Type::QuantumQubit, // Simplified: actual quantum literals might infer QReg
                    Literal::Nano(_, _) => Type::NanoAtom(Box::new(Type::Unknown)), // Simplified: depends on annotation
                    Literal::MTS(_, _) => Type::MTSValue,
                }
            }
            Expression::Prefix(span, op_type, right_expr) => {
                let right_type = self.analyze_expression(right_expr);
                match op_type {
                    TokenType::Bang => { // ! (logical NOT)
                        if right_type != Type::Boolean {
                            self.errors.push(SemanticError::new(
                                format!("Operator {:?} cannot be applied to type {:?}.", op_type, right_type),
                                span.clone(),
                            ));
                            Type::Error
                        } else {
                            Type::Boolean
                        }
                    }
                    TokenType::Minus => { // - (unary minus)
                        if right_type != Type::Int && right_type != Type::Float {
                            self.errors.push(SemanticError::new(
                                format!("Operator {:?} cannot be applied to type {:?}.", op_type, right_type),
                                span.clone(),
                            ));
                            Type::Error
                        } else {
                            right_type // Result type is same as operand type
                        }
                    }
                    _ => {
                        self.errors.push(SemanticError::new(
                            format!("Unsupported prefix operator {:?}.", op_type),
                            span.clone(),
                        ));
                        Type::Error
                    }
                }
            }
            Expression::Infix(span, left_expr, op_type, right_expr) => {
                let left_type = self.analyze_expression(left_expr);
                let right_type = self.analyze_expression(right_expr);

                match op_type {
                    TokenType::Plus | TokenType::Minus | TokenType::Star | TokenType::Slash => {
                        // Numeric operations
                        if left_type == Type::Int && right_type == Type::Int { Type::Int }
                        else if left_type == Type::Float && right_type == Type::Float { Type::Float }
                        else if left_type == Type::Int && right_type == Type::Float { Type::Float } // Promote int to float
                        else if left_type == Type::Float && right_type == Type::Int { Type::Float } // Promote int to float
                        else {
                            self.errors.push(SemanticError::new(
                                format!("Type mismatch for {:?} operator: cannot apply to {:?} and {:?}.", op_type, left_type, right_type),
                                span.clone(),
                            ));
                            Type::Error
                        }
                    }
                    TokenType::Equals | TokenType::NotEquals | TokenType::LT | TokenType::GT | TokenType::LTE | TokenType::GTE => {
                        // Comparison operations
                        if left_type == right_type && left_type.is_comparable() { Type::Boolean }
                        else {
                            self.errors.push(SemanticError::new(
                                format!("Type mismatch for {:?} operator: cannot compare {:?} and {:?}.", op_type, left_type, right_type),
                                span.clone(),
                            ));
                            Type::Error
                        }
                    }
                    TokenType::LogicalAnd | TokenType::LogicalOr => {
                        // Logical operations
                        if left_type == Type::Boolean && right_type == Type::Boolean { Type::Boolean }
                        else {
                            self.errors.push(SemanticError::new(
                                format!("Type mismatch for {:?} operator: expected booleans, found {:?} and {:?}.", op_type, left_type, right_type),
                                span.clone(),
                            ));
                            Type::Error
                        }
                    }
                    _ => {
                        self.errors.push(SemanticError::new(
                            format!("Unsupported infix operator {:?}.", op_type),
                            span.clone(),
                        ));
                        Type::Error
                    }
                }
            }
            Expression::If(span, cond_expr, then_block, else_block) => {
                let cond_type = self.analyze_expression(cond_expr);
                if cond_type != Type::Boolean {
                    self.errors.push(SemanticError::new(
                        "If condition must be of type Boolean.".to_string(),
                        span.clone(),
                    ));
                }
                let then_type = self.analyze_expression(then_block);
                let else_type = else_block.as_ref().map(|b| self.analyze_expression(b)).unwrap_or(Type::Unit); // else branch is optional, defaults to Unit
                // Conceptual: Ensure then_type and else_type are compatible
                if then_type != else_type && then_type != Type::Unit && else_type != Type::Unit && then_type != Type::Error && else_type != Type::Error {
                     self.errors.push(SemanticError::new(
                        format!("If/else branches must have compatible types; found {:?} and {:?}.", then_type, else_type),
                        span.clone(),
                    ));
                    Type::Error
                } else if then_type == Type::Error || else_type == Type::Error {
                    Type::Error
                } else {
                    if then_type != Type::Unit { then_type } else { else_type } // Return non-unit type if available
                }
            }
            Expression::Block(span, statements) => {
                self.symbol_table.enter_scope();
                for stmt in statements {
                    self.analyze_statement(stmt);
                }
                self.symbol_table.exit_scope();
                // Conceptual: The type of a block is the type of its last expression, or Unit if no expressions.
                Type::Unit // Simplified for now
            }
            Expression::Call(span, func_expr, args) => {
                let func_type = self.analyze_expression(func_expr);
                let arg_types: Vec<Type> = args.iter().map(|arg| self.analyze_expression(arg)).collect();

                // Conceptual: Perform function overload resolution and type checking for arguments
                if let Type::Function(param_types, return_type) = func_type {
                    // Simplified: Assuming `param_types` is a single type representing all params for conceptual purpose
                    // In real implementation, `param_types` would be `Vec<Type>` or similar
                    // if arg_types.len() != param_types.len() { /* error */ }
                    // for i in 0..arg_types.len() { /* check arg_types[i] against param_types[i] */ }
                    *return_type
                } else {
                    self.errors.push(SemanticError::new(
                        format!("Cannot call non-function type {:?}.", func_type),
                        span.clone(),
                    ));
                    Type::Error
                }
            }
            Expression::Index(span, array_expr, index_expr) => {
                let array_type = self.analyze_expression(array_expr);
                let index_type = self.analyze_expression(index_expr);

                if index_type != Type::Int {
                    self.errors.push(SemanticError::new(
                        format!("Array index must be an integer, found {:?}.", index_type),
                        span.clone(),
                    ));
                }
                // Conceptual: Check if array_type is indeed an array/list/vector type
                match array_type {
                    Type::Array(element_type) => *element_type,
                    _ => {
                        self.errors.push(SemanticError::new(
                            format!("Cannot index non-array type {:?}.", array_type),
                            span.clone(),
                        ));
                        Type::Error
                    }
                }
            }
        }
    }

    // Conceptual type assignability check (simplified)
    fn is_assignable(&self, from: &Type, to: &Type) -> bool {
        from == to || *from == Type::Error || *to == Type::Error ||
        (from == &Type::Int && to == &Type::Float) // Implicit integer to float conversion
        // Add more complex assignability rules here for Zenith's rich type system
    }


    pub fn get_errors(&self) -> &[SemanticError] {
        &self.errors
    }
}

// --- Conceptual Type System & Symbol Table ---
pub mod compiler_types {
    use std::collections::HashMap;
    use crate::tokens::Span;

    #[derive(Debug, Clone, PartialEq, Eq, Hash)]
    pub enum Type {
        Unknown,
        Error,
        Unit, // Represents absence of a value (like 'void')

        // Basic types
        Int,
        Float,
        Boolean,
        String,
        Char,

        // Composite types
        Array(Box<Type>), // e.g., Array<Int>
        Function(Box<Type>, Box<Type>), // (param_types, return_type) - Simplified

        // Zenith-specific types
        QuantumQubit,
        QuantumQReg(usize), // Quantum Register with N qubits
        QuantumSuperposition(Box<Type>), // Superposition<T>
        QuantumEntangled(Box<Type>, Box<Type>), // Entangled<A,B>
        QuantumMeasured(Box<Type>), // QMeasured<T>

        NanoAtom(Box<Type>), // Atom<Element>
        NanoMolecule(Box<Type>), // Molecule<Formula>
        NanoAgent,

        MTSValue, // Multi-Timeline System value

        // Type system types (from universe hierarchy)
        UniverseType(usize), // Type_N
        Kind,
        Sort,
        Prop,

        // Linear/Affine types
        Linear(Box<Type>),
        Affine(Box<Type>),

        // Effect system types
        Effect(String), // Effect("DivByZero")
        Effectful(Box<Type>, Vec<Type>), // T with effects

        // Sankofa-specific types
        SankofaMemory(Box<Type>), // A memory structure holding a value of Type
        SankofaHistory(Box<Type>), // History<Type, Span>
        SankofaConsensus(Box<Type>), // ConsensusTrue<Type>
        SankofaWisdom, // Wisdom<T, Source>
        SankofaInterMemory(String, Box<Type>), // InterMemory<Lang, Type>
    }

    impl Type {
        pub fn is_comparable(&self) -> bool {
            matches!(self, Type::Int | Type::Float | Type::Boolean | Type::String | Type::Char)
            // Can be extended for quantum/nano types later
        }
    }

    // --- Symbol Table ---
    #[derive(Debug, Clone)]
    pub struct Symbol {
        pub name: String,
        pub typ: Type,
        pub span: Span,
        // Add other symbol properties like mutability, visibility, etc.
    }

    #[derive(Debug, Clone)]
    pub struct Scope {
        symbols: HashMap<String, Symbol>,
        // Add parent scope reference
    }

    impl Scope {
        pub fn new() -> Self {
            Scope { symbols: HashMap::new() }
        }

        pub fn define(&mut self, name: String, typ: Type, span: Span) {
            self.symbols.insert(name.clone(), Symbol { name, typ, span });
        }

        pub fn resolve(&self, name: &str) -> Option<&Symbol> {
            // Search from innermost scope outwards
            for scope in self.scopes.iter().rev() {
                if let Some(symbol) = scope.resolve(name) {
                    return Some(symbol);
                }
            }
            None
        }
    }

    #[derive(Debug, Clone)]
    pub struct SymbolTable {
        scopes: Vec<Scope>,
    }

    impl SymbolTable {
        pub fn new() -> Self {
            SymbolTable { scopes: vec![Scope::new()] } // Start with a global scope
        }

        pub fn enter_scope(&mut self) {
            self.scopes.push(Scope::new());
        }

        pub fn exit_scope(&mut self) {
            if self.scopes.len() > 1 { // Don't remove the global scope
                self.scopes.pop();
            }
        }

        pub fn define_symbol(&mut self, name: String, typ: Type, span: Span) {
            if let Some(current_scope) = self.scopes.last_mut() {
                current_scope.define(name, typ, span);
            }
        }

        pub fn resolve_symbol(&self, name: &str) -> Option<&Symbol> {
            // Search from innermost scope outwards
            for scope in self.scopes.iter().rev() {
                if let Some(symbol) = scope.resolve(name) {
                    return Some(symbol);
                }
            }
            None
        }
    }

    // --- SemanticError for reporting ---
    #[derive(Debug, Clone, PartialEq, Eq)]
    pub struct SemanticError {
        pub message: String,
        pub span: Span,
    }

    impl SemanticError {
        pub fn new(message: String, span: Span) -> Self {
            SemanticError { message, span }
        }
    }
}
